// Catalog data: fetched at runtime from data/mods.json (generated by scripts/build.mjs).
// Every count, version and "new" flag on the site is derived here, never written into the HTML.

export const SHORT_TITLES = {
  core: 'Core',
  security: 'Guardrails',
  git: 'Git',
  cost: 'Cost & Context',
  productivity: 'Productivity',
  quality: 'Quality',
  observability: 'Panes',
  prompting: 'Prompting',
  notifications: 'Notifications',
  memory: 'Memory',
  team: 'Team & Docs',
  stacks: 'Stacks',
  devops: 'DevOps',
  data: 'Data',
  frontend: 'Frontend',
  api: 'APIs',
  agents: 'Agents',
  learning: 'Learning',
  compliance: 'Compliance',
  performance: 'Performance',
  ecosystem: 'Ecosystem',
}

export const ICON_IDS = new Set(Object.keys(SHORT_TITLES))

const TIERS = {
  simple: { label: 'Essential', bars: 1 },
  complex: { label: 'Advanced', bars: 3 },
}

export function tierOf(tier) {
  return TIERS[tier] ?? { label: tier ? tier[0].toUpperCase() + tier.slice(1) : 'Mod', bars: 2 }
}

export function shortTitle(category) {
  return SHORT_TITLES[category.id] ?? category.title
}

export function iconHref(categoryId) {
  return `#i-${ICON_IDS.has(categoryId) ? categoryId : 'core'}`
}

export function iconSvg(categoryId, className = 'icon') {
  return `<svg class="${className}" aria-hidden="true"><use href="${iconHref(categoryId)}"/></svg>`
}

export function installCommand(name, marketplace = 'claude-mods') {
  return `/plugin install ${name}@${marketplace}`
}

export function sourceUrl(name, repository) {
  return `https://github.com/${repository}/tree/main/mods/${encodeURIComponent(name)}`
}

export function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch])
}

/** Compares two dotted versions numerically: -1, 0 or 1. */
export function compareVersions(a = '0', b = '0') {
  const pa = String(a).split('.').map(Number)
  const pb = String(b).split('.').map(Number)
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] || 0) - (pb[i] || 0)
    if (d) return d > 0 ? 1 : -1
  }
  return 0
}

/** "2.0.0" -> "v2", "2.1.0" -> "v2.1", "2.1.3" -> "v2.1.3". */
export function versionLabel(version) {
  const parts = String(version).split('.')
  while (parts.length > 1 && parts[parts.length - 1] === '0') parts.pop()
  return `v${parts.join('.')}`
}

let pending = null

export function loadCatalog() {
  pending ??= fetch('data/mods.json', { credentials: 'same-origin' })
    .then(response => {
      if (!response.ok) throw new Error(`mods.json: ${response.status}`)
      return response.json()
    })
    .then(normalise)
  return pending
}

function normalise(raw) {
  const repository = raw.repository || 'plagemes/claude-mods'
  const allCategories = (raw.categories ?? []).map(c => ({ ...c, short: shortTitle(c) }))
  const byId = new Map(allCategories.map(c => [c.id, c]))
  const mods = (raw.mods ?? []).map((m, index) => ({
    ...m,
    index,
    since: m.since ?? '1.0.0',
    keywords: m.keywords ?? [],
    commands: m.commands ?? [],
    categoryInfo: byId.get(m.category) ?? { id: m.category, title: m.category, short: m.category, tagline: '' },
  }))

  // Releases present in the data, oldest first. The newest one (if it is not the first) is "new".
  const releases = [...new Set(mods.map(m => m.since))].sort(compareVersions)
  const latest = releases[releases.length - 1] ?? '1.0.0'
  const hasNew = releases.length > 1
  for (const m of mods) m.isNew = hasNew && m.since === latest

  // Only categories that actually hold mods are shown; each remembers the release that introduced it.
  const categories = allCategories
    .map(c => {
      const inCat = mods.filter(m => m.category === c.id)
      const since = inCat.map(m => m.since).sort(compareVersions)[0] ?? latest
      return { ...c, count: inCat.length, since, isNew: hasNew && inCat.length > 0 && inCat.every(m => m.isNew) }
    })
    .filter(c => c.count > 0)

  const newMods = mods.filter(m => m.isNew)
  const release = {
    version: raw.version ?? latest,
    label: versionLabel(raw.version ?? latest),
    newLabel: versionLabel(latest),
    newSince: hasNew ? latest : null,
    newCount: newMods.length,
    newCategories: categories.filter(c => c.isNew),
    releases,
  }

  return { repository, marketplace: raw.marketplace, version: release.version, release, categories, mods, newMods, byName: new Map(mods.map(m => [m.name, m])) }
}
